functions._cdlHash:
function _cdlHash(s) {
  var str = String(s == null ? "" : s), h = 5381, i = str.length;
  while (i) { h = (h * 33) ^ str.charCodeAt(--i); }
  return "h" + (h >>> 0).toString(16);
}

functions._cdlTokenize:
function _cdlTokenize(s) {
  // Lossless: captures whitespace runs AND non-whitespace runs separately, so
  // joining the tokens reproduces the input EXACTLY (needed for reconstruct).
  var m = String(s == null ? "" : s).match(/\s+|\S+/g);
  return m || [];
}

functions._cdlSimilarity:
function _cdlSimilarity(a, b) {
  var ta = _cdlNormalize(a).split(" ").filter(Boolean);
  var tb = _cdlNormalize(b).split(" ").filter(Boolean);
  if (!ta.length && !tb.length) return 1;
  if (!ta.length || !tb.length) return 0;
  var bag = {}, i, inter = 0;
  for (i = 0; i < tb.length; i++) bag[tb[i]] = (bag[tb[i]] || 0) + 1;
  for (i = 0; i < ta.length; i++) { if (bag[ta[i]] > 0) { inter++; bag[ta[i]]--; } }
  return (2 * inter) / (ta.length + tb.length);
}

// ── Template handling: decompress + plain text + neutralize placeholders ──

functions._cdlDecompressTemplate:
function _cdlDecompressTemplate(rec) {
  // bd_templates rows carry `_z:true` + `content` = pako-deflate bytes, else a
  // plain string. FROM template_searcher._bdDecompress. (Fallback path only —
  // the primary loader reuses window.tsLoadTemplates.)
  if (!rec) return "";
  if (rec._z && rec.content && window.pako && typeof window.pako.inflate === "function") {
    try { return new TextDecoder().decode(window.pako.inflate(rec.content)); }
    catch (e) { return ""; }
  }
  return String(rec.content || "");
}

functions._cdlExtractPlainText:
function _cdlExtractPlainText(raw) {
  // FROM template_searcher._tsExtractPlainText, extended to PRESERVE paragraph
  // boundaries (insert \n at block starts before stripping tags) so OOXML/HTML
  // templates segment into clauses instead of collapsing to one line.
  if (!raw) return "";
  var text = raw;
  if (raw.charAt(0) === "{" || raw.charAt(0) === "[") {
    try {
      var obj = JSON.parse(raw);
      if (obj && typeof obj === "object") {
        if (typeof obj.text === "string" && obj.text.length) text = obj.text;
        else if (typeof obj.html === "string" && obj.html.length) text = obj.html;
        else if (typeof obj.ooxml === "string" && obj.ooxml.length) text = obj.ooxml;
        else if (Array.isArray(obj.ops)) {
          text = obj.ops.map(function (o) { return (o && typeof o.insert === "string") ? o.insert : ""; }).join("");
        }
      }
    } catch (e) { /* not JSON */ }
  }
  text = text
    .replace(/<w:p\b/gi, "\n<w:p")
    .replace(/<\/w:p>/gi, "\n")
    .replace(/<p\b/gi, "\n<p")
    .replace(/<\/p>/gi, "\n")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/tr>/gi, "\n");
  text = text.replace(/<[^>]+>/g, " ");
  text = text.replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
  text = text.replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n").replace(/[ \t]{2,}/g, " ");
  return text.trim();
}

functions._cdlStripTemplate:
function _cdlStripTemplate(text) {
  // Neutralize Build Draft authoring tokens so they don't diff as noise vs the
  // filled/executed final. NOTE: {{IF}}…{{ELSE}}…{{END}} leaves BOTH branch
  // texts inline — logic branch resolution is the next step; for now the
  // baseline stays editable so the unused branch can be deleted by hand.
  var t = String(text == null ? "" : text);
  t = t.replace(/\{\{[^{}]*\}\}/g, "");                 // {{IF/ELSE/END/DEF/TITLE}}
  t = t.replace(/\$?\!?\[\[[^\]]*\]\]/g, "[…]");         // [[Field]] (+ rare $/! prefixes)
  t = t.replace(/\$\!\[[^\]]*\]/g, "[…]");              // $![Payment trigger]
  t = t.replace(/\$\[[^\]]*\]/g, "[…]");                // $[Currency]
  t = t.replace(/\!\[[^\]]*\]/g, "[…]");                // ![Payment candidate]
  t = t.replace(/[ \t]{2,}/g, " ");
  return t;
}

functions._cdlLoadTemplates:
function _cdlLoadTemplates(eli) {
  // Reuse template_searcher's parser (envelope split + OOXML→plainText + pako
  // decompress) instead of reimplementing it. ensureLoaded warms the demand-
  // tier bundle so window.tsLoadTemplates exists; fall back to a local parse
  // only if template_searcher isn't installed.
  function _fromSearcher() {
    if (typeof window.tsLoadTemplates !== "function") return null;
    return Promise.resolve(window.tsLoadTemplates()).then(function (rows) {
      return (rows || []).map(function (t) {
        // Prefer the per-paragraph array (guaranteed one clause-line per
        // paragraph) over the flat .content string.
        var plain = (Array.isArray(t.paragraphs) && t.paragraphs.length)
          ? t.paragraphs.map(function (p) { return (p && p.plainText) || ""; }).join("\n")
          : String(t.content || "");
        return { id: t.id, name: t.name || t.id, plain: plain };
      }).filter(function (t) { return t.plain && t.plain.length; })
        .sort(function (a, b) { return String(a.name).localeCompare(String(b.name)); });
    });
  }
  var ensure = (eli.tools && eli.tools.ensureLoaded)
    ? Promise.resolve(eli.tools.ensureLoaded("template_searcher")).catch(function () {})
    : Promise.resolve();
  return ensure.then(function () {
    var viaSearcher = _fromSearcher();
    if (viaSearcher) return viaSearcher;
    return eli.storage.getAll("bd_templates").then(function (rows) {
      return (rows || [])
        .filter(function (r) { return r && r.id && String(r.id).charAt(0) !== "_"; })
        .map(function (rec) {
          var plain = "";
          try { plain = _cdlExtractPlainText(_cdlDecompressTemplate(rec)); } catch (e) {}
          return { id: rec.id, name: rec.name || rec.id, plain: plain };
        })
        .filter(function (t) { return t.plain && t.plain.length; })
        .sort(function (a, b) { return String(a.name).localeCompare(String(b.name)); });
    });
  });
}

// ── Segmentation: paragraph / section aware (fixes "whole document" diff) ──

functions._cdlIsHeading:
function _cdlIsHeading(p) {
  var s = String(p || "").trim();
  if (!s) return false;
  if (/^(ARTICLE|SECTION|EXHIBIT|SCHEDULE|APPENDIX|ANNEX|RECITALS|PREAMBLE)\b/i.test(s)) return true;
  if (/^\d+(\.\d+)*\.?[\s\)\.—:-]+\S/.test(s)) return true;     // 1.  1.2)  12 —
  if (/^\([a-z0-9]{1,4}\)\s*\S/i.test(s)) return true;              // (a) (iv) (1)
  // Short ALL-CAPS line → likely a heading.
  if (/^[A-Z][A-Z0-9 ,'&/\-]{3,46}[.:]?$/.test(s) && s.split(/\s+/).length <= 8) return true;
  return false;
}

functions._cdlHeading:
function _cdlHeading(t) {
  var firstLine = String(t == null ? "" : t).split("\n")[0];
  var m = firstLine.match(/^\s*((?:Article|Section|Exhibit|Schedule)?\s*\d+(?:\.\d+)*)[\.\)\s]/i);
  var num = m ? m[1].replace(/\s+/g, " ").trim() : "";
  var words = firstLine.trim().split(/\s+/).slice(0, 9).join(" ");
  if (words.length > 64) words = words.slice(0, 64) + "…";
  return (num && words.toLowerCase().indexOf(num.toLowerCase()) !== 0)
    ? num + " · " + words
    : (words || "(untitled clause)");
}

functions._cdlSegment:
function _cdlSegment(text) {
  // Split into paragraphs (Word body.text uses \r per paragraph), then group
  // into clauses by section heading. No headings detected → paragraph = clause.
  var raw = String(text == null ? "" : text).replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  var paras = raw.split(/\n/)
    .map(function (p) { return p.replace(/^\s+|\s+$/g, ""); })
    .filter(function (p) { return p.length; });
  if (!paras.length) return [];
  var anyHeading = paras.some(_cdlIsHeading);
  var out = [];
  if (!anyHeading) {
    paras.forEach(function (p) { out.push({ idx: out.length, text: p, heading: _cdlHeading(p) }); });
    return out;
  }
  var cur = null;
  paras.forEach(function (p) {
    if (cur === null || _cdlIsHeading(p)) {
      if (cur) out.push(cur);
      cur = { idx: out.length, text: p, heading: _cdlHeading(p) };
    } else {
      cur.text += "\n" + p;
    }
  });
  if (cur) out.push(cur);
  return out;
}

functions._cdlWordDiff:
function _cdlWordDiff(a, b) {
  var A = _cdlTokenize(a), B = _cdlTokenize(b);
  var n = A.length, m = B.length;
  if (n * m > 4000000) {
    var coarse = [];
    if (a) coarse.push({ op: "del", text: a });
    if (b) coarse.push({ op: "ins", text: b });
    coarse._coarse = true;
    return coarse;
  }
  var dp = [], i, j;
  for (i = 0; i <= n; i++) { var row = new Array(m + 1); for (j = 0; j <= m; j++) row[j] = 0; dp.push(row); }
  for (i = n - 1; i >= 0; i--) {
    for (j = m - 1; j >= 0; j--) {
      dp[i][j] = (A[i] === B[j]) ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  var ops = [], ii = 0, jj = 0;
  function push(op, text) {
    var last = ops[ops.length - 1];
    if (last && last.op === op) last.text += text; else ops.push({ op: op, text: text });
  }
  while (ii < n && jj < m) {
    if (A[ii] === B[jj]) { push("eq", A[ii]); ii++; jj++; }
    else if (dp[ii + 1][jj] >= dp[ii][jj + 1]) { push("del", A[ii]); ii++; }
    else { push("ins", B[jj]); jj++; }
  }
  while (ii < n) { push("del", A[ii]); ii++; }
  while (jj < m) { push("ins", B[jj]); jj++; }
  return ops;
}

functions._cdlReconstruct:
function _cdlReconstruct(ops) {
  var out = "";
  (ops || []).forEach(function (o) { if (o.op === "eq" || o.op === "ins") out += o.text; });
  return out;
}

functions._cdlDiffStats:
function _cdlDiffStats(ops) {
  var ins = 0, del = 0, eq = 0;
  (ops || []).forEach(function (o) {
    var n = _cdlTokenize(o.text).filter(function (t) { return /\S/.test(t); }).length;
    if (o.op === "ins") ins += n; else if (o.op === "del") del += n; else eq += n;
  });
  return { insertedTokens: ins, deletedTokens: del, keptTokens: eq };
}

functions._cdlSectionKey:
function _cdlSectionKey(text) {
  // Leading section identifier from a clause's first line: "5", "5.1", "(a)".
  var first = String(text == null ? "" : text).split("\n")[0];
  var m = first.match(/^\s*(\d+(?:\.\d+)*)(?=[\s\).:—-]|$)/);
  if (m) return m[1];
  var a = first.match(/^\s*\(([a-z0-9]{1,3})\)/i);
  if (a) return "(" + a[1].toLowerCase() + ")";
  return "";
}

functions._cdlAlign:
function _cdlAlign(origArr, finalArr, threshold) {
  // Order-aware sequence alignment (Needleman-Wunsch) over clauses, with a
  // section-number anchor: "§5 ↔ §5" pairs even when heavily edited. Gaps =
  // added/omitted; a too-weak diagonal splits into omitted+added rather than a
  // bogus "modified". Respects document order — fixes the greedy mis-pairing.
  threshold = (typeof threshold === "number") ? threshold : 0.4;
  var n = origArr.length, m = finalArr.length, i, j;
  function score(io, jf) {
    var s = _cdlSimilarity(origArr[io].text, finalArr[jf].text);
    var ko = _cdlSectionKey(origArr[io].text), kf = _cdlSectionKey(finalArr[jf].text);
    if (ko && kf && ko === kf) s = Math.min(1, s + 0.4); // same § number → strong anchor
    return s;
  }
  var dp = [];
  for (i = 0; i <= n; i++) { var row = []; for (j = 0; j <= m; j++) row.push(0); dp.push(row); }
  for (i = 1; i <= n; i++) {
    for (j = 1; j <= m; j++) {
      // Gap penalty 0 — gaps are legitimate added/omitted clauses.
      dp[i][j] = Math.max(dp[i - 1][j - 1] + score(i - 1, j - 1), dp[i - 1][j], dp[i][j - 1]);
    }
  }
  function omit(o) { return { state: "omitted", origIdx: o.idx, finalIdx: null, origText: o.text, finalText: "", heading: o.heading, origHeading: o.heading, similarity: 0 }; }
  function add(f) { return { state: "added", origIdx: null, finalIdx: f.idx, origText: "", finalText: f.text, heading: f.heading, similarity: 0 }; }
  var slots = [];
  i = n; j = m;
  while (i > 0 && j > 0) {
    var sc = score(i - 1, j - 1);
    var dgi = dp[i - 1][j - 1] + sc, upi = dp[i - 1][j], lfi = dp[i][j - 1];
    var best = Math.max(dgi, upi, lfi);
    if (best === dgi) {
      if (sc >= threshold) {
        var oc = origArr[i - 1], fc = finalArr[j - 1];
        var identical = _cdlNormalize(oc.text) === _cdlNormalize(fc.text);
        slots.push({
          state: identical ? "unchanged" : "modified",
          origIdx: oc.idx, finalIdx: fc.idx, origText: oc.text, finalText: fc.text,
          heading: fc.heading || oc.heading, origHeading: oc.heading, similarity: sc,
        });
      } else {
        slots.push(add(finalArr[j - 1]));
        slots.push(omit(origArr[i - 1]));
      }
      i--; j--;
    } else if (best === upi) { slots.push(omit(origArr[i - 1])); i--; }
    else { slots.push(add(finalArr[j - 1])); j--; }
  }
  while (i > 0) { slots.push(omit(origArr[i - 1])); i--; }
  while (j > 0) { slots.push(add(finalArr[j - 1])); j--; }
  slots.reverse();
  return slots;
}

functions._cdlBuildRecord:
function _cdlBuildRecord(slot, ctx) {
  var rec = {
    id: "cdl_" + ctx.sessionTs + "_" + ctx.idx,
    tool: "clause_diff_lab",
    state: slot.state,
    heading: slot.heading || "",
    baselineHeading: slot.origHeading || "",
    similarity: Number((slot.similarity || 0).toFixed(3)),
    baselineRef: ctx.baselineRef || null,
    provenance: {
      toolVersion: ctx.toolVersion || "test",
      kernelVersion: ctx.kernelVersion || "",
      timestamp: ctx.timestamp,
    },
  };
  if (slot.state === "unchanged") {
    rec.baselineHash = _cdlHash(_cdlNormalize(slot.origText));
  } else if (slot.state === "modified") {
    rec.baselineHash = _cdlHash(_cdlNormalize(slot.origText));
    rec.diffOps = _cdlWordDiff(slot.origText, slot.finalText);
    rec.diffStats = _cdlDiffStats(rec.diffOps);
  } else if (slot.state === "added") {
    rec.finalText = slot.finalText;
  } else if (slot.state === "omitted") {
    rec.baselineHash = _cdlHash(_cdlNormalize(slot.origText));
  }
  // Test-only scaffolding — raw clause text kept so the redline view can
  // render. In the real system this stays LOCAL and is never shared.
  rec._test = { origText: slot.origText, finalText: slot.finalText };
  return rec;
}

functions._cdlAnalyze:
function _cdlAnalyze(origText, finalText, ctx) {
  ctx = ctx || {};
  var origArr = _cdlSegment(origText);
  var finalArr = _cdlSegment(finalText);
  var slots = _cdlAlign(origArr, finalArr, ctx.threshold);
  var records = slots.map(function (slot, i) {
    return _cdlBuildRecord(slot, {
      sessionTs: ctx.sessionTs, idx: i, baselineRef: ctx.baselineRef,
      toolVersion: ctx.toolVersion, kernelVersion: ctx.kernelVersion, timestamp: ctx.timestamp,
    });
  });
  var counts = { unchanged: 0, modified: 0, added: 0, omitted: 0 };
  slots.forEach(function (s) { counts[s.state]++; });
  return {
    items: records, slots: slots, counts: counts,
    origCount: origArr.length, finalCount: finalArr.length,
    overview: origArr.length + " baseline / " + finalArr.length + " document clauses · " +
      counts.modified + " modified, " + counts.added + " added, " +
      counts.omitted + " omitted, " + counts.unchanged + " unchanged",
    provenance: { timestamp: ctx.timestamp, kernelVersion: ctx.kernelVersion, toolVersion: ctx.toolVersion },
  };
}

// ─── Redline rendering (inline styles for guaranteed paint) ─────────────

functions._cdlRenderOps:
function _cdlRenderOps(ops) {
  var DEL = "text-decoration:line-through;color:#b3261e;background:#fde8e6;border-radius:2px;";
  var INS = "text-decoration:underline;color:#0b6b3a;background:#e6f4ea;border-radius:2px;";
  var html = "";
  (ops || []).forEach(function (o) {
    var t = _cdlEsc(o.text);
    if (o.op === "del") html += '<span style="' + DEL + '">' + t + "</span>";
    else if (o.op === "ins") html += '<span style="' + INS + '">' + t + "</span>";
    else html += t;
  });
  return html;
}

functions._cdlRenderRedline:
function _cdlRenderRedline(rec) {
  if (rec.state === "unchanged") {
    return '<div class="_cdl_note _cdl_note_ok">✓ Identical to baseline (' + _cdlEsc(rec.baselineHash) +
      ") — stored as a pointer only.</div>";
  }
  if (rec.state === "added") {
    var insStyle = "text-decoration:underline;color:#0b6b3a;background:#e6f4ea;border-radius:2px;";
    return '<div class="_cdl_note _cdl_note_add">＋ In document, no baseline match (counterparty-added / new). Stored as full text (Tier 2).</div>' +
      '<div class="_cdl_redline"><span style="' + insStyle + '">' + _cdlEsc(rec._test.finalText) + "</span></div>";
  }
  if (rec.state === "omitted") {
    var delStyle = "text-decoration:line-through;color:#b3261e;background:#fde8e6;border-radius:2px;";
    return '<div class="_cdl_note _cdl_note_del">－ In baseline, omitted from document. Stored as a near-empty signal.</div>' +
      '<div class="_cdl_redline"><span style="' + delStyle + '">' + _cdlEsc(rec._test.origText) + "</span></div>";
  }
  var recon = _cdlReconstruct(rec.diffOps);
  var ok = (recon === rec._test.finalText);
  var badge = ok
    ? '<span class="_cdl_recon _cdl_recon_ok">✓ Reconstruct matches document</span>'
    : '<span class="_cdl_recon _cdl_recon_bad">✗ Reconstruct MISMATCH</span>';
  var coarse = rec.diffOps && rec.diffOps._coarse
    ? '<div class="_cdl_note _cdl_note_warn">⚠ Clause too large for token diff — stored as whole replace.</div>' : "";
  return coarse +
    '<div class="_cdl_redline">' + _cdlRenderOps(rec.diffOps) + "</div>" +
    '<div class="_cdl_reconrow">' + badge +
    ' <span class="_cdl_dim">' + rec.diffStats.insertedTokens + " ins · " +
    rec.diffStats.deletedTokens + " del · " + rec.diffStats.keptTokens + " kept</span></div>";
}

functions._cdlRenderCard:
function _cdlRenderCard(rec) {
  function badge(state) {
    var map = {
      unchanged: ["UNCHANGED", "_cdl_b_unch"], modified: ["MODIFIED", "_cdl_b_mod"],
      added: ["ADDED", "_cdl_b_add"], omitted: ["OMITTED", "_cdl_b_omit"],
    };
    var m = map[state] || [String(state).toUpperCase(), ""];
    return '<span class="_cdl_badge ' + m[1] + '">' + m[0] + "</span>";
  }
  var durable = {};
  Object.keys(rec).forEach(function (k) { if (k !== "_test") durable[k] = rec[k]; });
  var sim = (rec.state === "modified" || rec.state === "unchanged")
    ? ' <span class="_cdl_dim">sim ' + (rec.similarity != null ? rec.similarity : "—") + "</span>" : "";
  return '<div class="_cdl_card _cdl_card_' + rec.state + '">' +
    '<div class="_cdl_cardhdr">' + badge(rec.state) +
      '<span class="_cdl_cardtitle">' + _cdlEsc(rec.heading || "(untitled)") + "</span>" + sim +
      '<span class="_cdl_cardid">' + _cdlEsc(rec.id) + "</span>" +
    "</div>" +
    ((rec.state === "modified" || rec.state === "unchanged") && rec.baselineHeading
      ? '<div class="_cdl_pair">paired with baseline: <b>' + _cdlEsc(rec.baselineHeading) + "</b></div>" : "") +
    '<div class="_cdl_seg">' +
      '<button class="_cdl_segbtn _cdl_seg_active" data-cdl-toggle="redline">Redline</button>' +
      '<button class="_cdl_segbtn" data-cdl-toggle="record">Saved record</button>' +
      '<button class="_cdl_segbtn" data-cdl-toggle="raw">Raw text</button>' +
    "</div>" +
    '<div class="_cdl_pane" data-cdl-pane="redline" style="display:block;">' + _cdlRenderRedline(rec) + "</div>" +
    '<div class="_cdl_pane" data-cdl-pane="record" style="display:none;">' +
      '<div class="_cdl_recordcap">Exactly what is stored in IDB. <b>_test</b> (raw clause text) is lab-only scaffolding — in the real system it stays local and is never shared.</div>' +
      '<pre class="_cdl_json">' + _cdlEsc(JSON.stringify(durable, null, 2)) + "</pre>" +
    "</div>" +
    '<div class="_cdl_pane" data-cdl-pane="raw" style="display:none;">' +
      '<div class="_cdl_rawgrid">' +
        '<div><div class="_cdl_rawlbl">BASELINE</div><pre class="_cdl_raw">' + _cdlEsc(rec._test ? rec._test.origText : "") + "</pre></div>" +
        '<div><div class="_cdl_rawlbl">DOCUMENT</div><pre class="_cdl_raw">' + _cdlEsc(rec._test ? rec._test.finalText : "") + "</pre></div>" +
      "</div>" +
    "</div>" +
  "</div>";
}

functions._cdlNowFallback:
function _cdlNowFallback() {
  try { return Date.now(); } catch (e) { return 0; }
}

functions._cdlReadDocParagraphs:
function _cdlReadDocParagraphs(eli) {
  // Read the live doc PARAGRAPH BY PARAGRAPH (not body.text). body.text joins
  // paragraphs with \r, which some Word builds don't surface as a break our
  // segmenter catches — collapsing the whole doc into one clause. Loading
  // body.paragraphs guarantees one line per paragraph.
  if (eli.host && typeof eli.host.runRaw === "function") {
    return eli.host.runRaw("clause_diff_lab:read_paragraphs", function (ctx) {
      var paras = ctx.document.body.paragraphs;
      paras.load("text");
      return ctx.sync().then(function () {
        var lines = [];
        for (var i = 0; i < paras.items.length; i++) lines.push(paras.items[i].text || "");
        return lines.join("\n");
      });
    });
  }
  if (eli.host && typeof eli.host.readText === "function") return eli.host.readText({});
  return Promise.reject(new Error("Word host unavailable"));
}

