functions.showClauseDiffLab:
function showClauseDiffLab(eli) {
  var host = (eli && eli.ui && typeof eli.ui.claimOutput === "function")
    ? eli.ui.claimOutput()
    : document.getElementById("output");
  if (!host) return;

  var templates = [];        // [{ id, name, plain }]
  var templatesLoaded = false;

  host.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_cdl_root";
  host.appendChild(root);

  root.innerHTML =
    '<div class="_cdl_header">' +
      '<div class="_cdl_eyebrow">ADMIN · NEGOTIATION CAPTURE TEST</div>' +
      '<div class="_cdl_title">🧪 Clause Diff Lab</div>' +
      '<div class="_cdl_sub">Pick a <b>Build Draft template</b> as the baseline and diff the <b>current Word document</b> against it. ' +
      'ELI segments both into clauses, aligns them, stores a diff record per clause in IDB, and shows the saved record + a redline reconstruction.</div>' +
    "</div>" +
    '<div class="_cdl_tplbar">' +
      '<span class="_cdl_tpllbl">Baseline template:</span>' +
      '<select class="_cdl_select" id="_cdl_tplsel"><option value="">— loading templates… —</option></select>' +
      '<label class="_cdl_chk"><input type="checkbox" id="_cdl_strip" checked> Strip placeholders &amp; logic</label>' +
      '<button class="_cdl_btn _cdl_btn_primary" id="_cdl_run_real">⚖ Diff current document vs template</button>' +
    "</div>" +
    '<div class="_cdl_inputs">' +
      '<div class="_cdl_col">' +
        '<div class="_cdl_collabel">BASELINE <span class="_cdl_dim">(from template — editable)</span>' +
          '<button class="_cdl_btn _cdl_btn_ghost _cdl_btn_sm" id="_cdl_load_tpl">↻ Load selected template</button>' +
        "</div>" +
        '<textarea class="_cdl_ta" id="_cdl_orig" placeholder="Select a Build Draft template above and click Load — or paste baseline text here…"></textarea>' +
      "</div>" +
      '<div class="_cdl_col">' +
        '<div class="_cdl_collabel">DOCUMENT <span class="_cdl_dim">(executed / final)</span>' +
          '<button class="_cdl_btn _cdl_btn_ghost _cdl_btn_sm" id="_cdl_load_final">⬇ Load current doc</button>' +
        "</div>" +
        '<textarea class="_cdl_ta" id="_cdl_final" placeholder="Click Load current doc — or paste the final contract here…"></textarea>' +
      "</div>" +
    "</div>" +
    '<div class="_cdl_controls">' +
      '<label class="_cdl_thresh">Match threshold ' +
        '<input type="range" id="_cdl_thresh" min="0.2" max="0.9" step="0.05" value="0.4">' +
        '<span id="_cdl_thresh_val">0.40</span></label>' +
      '<div class="_cdl_controls_actions">' +
        '<button class="_cdl_btn _cdl_btn_ghost" id="_cdl_run">Run diff (use boxes)</button>' +
        '<button class="_cdl_btn _cdl_btn_ghost" id="_cdl_view_saved">📦 View saved (IDB)</button>' +
        '<button class="_cdl_btn _cdl_btn_ghost" id="_cdl_clear_saved">🗑 Clear test records</button>' +
      "</div>" +
    "</div>" +
    '<div class="_cdl_status" id="_cdl_status"></div>' +
    '<div class="_cdl_results" id="_cdl_results"></div>';

  var origEl = root.querySelector("#_cdl_orig");
  var finalEl = root.querySelector("#_cdl_final");
  var resultsEl = root.querySelector("#_cdl_results");
  var statusEl = root.querySelector("#_cdl_status");
  var threshEl = root.querySelector("#_cdl_thresh");
  var threshVal = root.querySelector("#_cdl_thresh_val");
  var tplSel = root.querySelector("#_cdl_tplsel");
  var stripEl = root.querySelector("#_cdl_strip");

  function _status(msg, kind) {
    statusEl.textContent = msg || "";
    statusEl.className = "_cdl_status" + (kind ? " _cdl_status_" + kind : "");
  }
  threshEl.oninput = function () { threshVal.textContent = Number(threshEl.value).toFixed(2); };

  // ── Load template list into the picker ──
  function _loadTemplates() {
    _status("Loading Build Draft templates…");
    return _cdlLoadTemplates(eli).then(function (list) {
      templates = list || [];
      templatesLoaded = true;
      var opts = '<option value="">— choose a template —</option>';
      templates.forEach(function (t) {
        opts += '<option value="' + _cdlEsc(t.id) + '">' + _cdlEsc(t.name) + " (" + t.plain.length + " chars)</option>";
      });
      if (!templates.length) opts = '<option value="">(no Build Draft templates found)</option>';
      tplSel.innerHTML = opts;
      _status(templates.length + " template(s) available.", templates.length ? "ok" : "warn");
      return templates;
    }).catch(function (e) {
      tplSel.innerHTML = '<option value="">(failed to load templates)</option>';
      _status("Template load failed: " + (e && e.message || "unknown"), "err");
    });
  }
  _loadTemplates();

  function _selectedTemplate() {
    var id = tplSel.value;
    if (!id) return null;
    for (var i = 0; i < templates.length; i++) if (templates[i].id === id) return templates[i];
    return null;
  }

  function _loadTemplateIntoBaseline() {
    var t = _selectedTemplate();
    if (!t) { _status("Pick a template first.", "warn"); return false; }
    origEl.value = stripEl.checked ? _cdlStripTemplate(t.plain) : t.plain;
    _status('Loaded "' + t.name + '" into baseline (' + origEl.value.length + " chars" +
      (stripEl.checked ? ", placeholders/logic stripped" : "") + ").", "ok");
    return true;
  }
  root.querySelector("#_cdl_load_tpl").onclick = _loadTemplateIntoBaseline;

  function _loadCurrentDoc() {
    _status("Reading current document (by paragraph)…");
    return _cdlReadDocParagraphs(eli).then(function (txt) {
      finalEl.value = txt || "";
      var n = (txt || "").split(/\n/).filter(function (l) { return l.trim(); }).length;
      _status("Loaded " + n + " paragraph(s) / " + (txt ? txt.length : 0) + " chars from the document.", "ok");
      return txt || "";
    });
  }
  root.querySelector("#_cdl_load_final").onclick = function () {
    _loadCurrentDoc().catch(function (e) { _status("Load failed: " + (e && e.message || "unknown"), "err"); });
  };

  // ── Run helpers ──
  function _run(baselineRefName) {
    var orig = origEl.value || "", final = finalEl.value || "";
    if (!orig.trim() || !final.trim()) { _status("Need both a baseline and a document.", "warn"); return; }
    var nowTs = _cdlNowFallback();
    var result;
    try {
      result = _cdlAnalyze(orig, final, {
        sessionTs: nowTs, threshold: Number(threshEl.value), baselineRef: baselineRefName || null,
        toolVersion: "test", kernelVersion: (eli && eli.kernelVersion) || "", timestamp: nowTs,
      });
    } catch (e) {
      _status("Diff failed: " + (e && e.message || "unknown"), "err");
      try { eli.log.event("tool", "clause_diff_lab_analyze_failed", { msg: e && e.message }); } catch (_e) {}
      return;
    }
    var puts = result.items.map(function (rec) {
      return eli.storage.put("negotiation_log", rec).catch(function (e) {
        try { eli.log.event("tool", "clause_diff_lab_put_failed", { id: rec.id, msg: e && e.message }); } catch (_e) {}
      });
    });
    Promise.all(puts).then(function () {
      _status("Captured " + result.items.length + " clause record(s) to IDB (negotiation_log).", "ok");
    });
    _renderResults(result);
  }

  root.querySelector("#_cdl_run").onclick = function () { _run(null); };

  root.querySelector("#_cdl_run_real").onclick = function () {
    if (!templatesLoaded) { _status("Templates still loading — try again in a moment.", "warn"); return; }
    var t = _selectedTemplate();
    if (!t) { _status("Pick a baseline template first.", "warn"); return; }
    _loadTemplateIntoBaseline();
    _status("Reading current document…");
    _loadCurrentDoc().then(function () { _run(t.name); })
      .catch(function (e) { _status("Could not read the document: " + (e && e.message || "unknown"), "err"); });
  };

  root.querySelector("#_cdl_view_saved").onclick = function () { _renderSaved(); };
  root.querySelector("#_cdl_clear_saved").onclick = function () {
    eli.ui.confirm({
      title: "Clear test records?",
      message: "Delete all clause_diff_lab records (ids starting cdl_) from the negotiation_log IDB store? Nothing else is touched.",
      confirmText: "Delete", cancelText: "Cancel",
    }).then(function (ok) {
      if (!ok) return;
      eli.storage.getAll("negotiation_log").then(function (rows) {
        var mine = (rows || []).filter(function (r) { return r && typeof r.id === "string" && r.id.indexOf("cdl_") === 0; });
        return Promise.all(mine.map(function (r) { return eli.storage.delete("negotiation_log", r.id); }))
          .then(function () { _status("Deleted " + mine.length + " test record(s).", "ok"); resultsEl.innerHTML = ""; });
      });
    });
  };

  // ── One-section-per-box stepped viewer ──
  var _stepItems = [], _stepIdx = 0;

  function _summaryHtml(result) {
    var c = result.counts;
    return '<div class="_cdl_summary">' +
      '<div class="_cdl_sumtile"><div class="_cdl_sumn">' + result.origCount + "</div><div class='_cdl_suml'>baseline clauses</div></div>" +
      '<div class="_cdl_sumtile"><div class="_cdl_sumn">' + result.finalCount + "</div><div class='_cdl_suml'>doc clauses</div></div>" +
      '<div class="_cdl_sumtile _cdl_t_mod"><div class="_cdl_sumn">' + c.modified + "</div><div class='_cdl_suml'>modified</div></div>" +
      '<div class="_cdl_sumtile _cdl_t_add"><div class="_cdl_sumn">' + c.added + "</div><div class='_cdl_suml'>added</div></div>" +
      '<div class="_cdl_sumtile _cdl_t_omit"><div class="_cdl_sumn">' + c.omitted + "</div><div class='_cdl_suml'>omitted</div></div>" +
      '<div class="_cdl_sumtile _cdl_t_unch"><div class="_cdl_sumn">' + c.unchanged + "</div><div class='_cdl_suml'>unchanged</div></div>" +
      "</div>";
  }

  function _renderResults(result) { _renderStepper(result.items, _summaryHtml(result)); }

  function _renderSaved() {
    _status("Loading saved records…");
    eli.storage.getAll("negotiation_log").then(function (rows) {
      var mine = (rows || []).filter(function (r) { return r && typeof r.id === "string" && r.id.indexOf("cdl_") === 0; });
      if (!mine.length) { resultsEl.innerHTML = '<div class="_cdl_empty">No saved test records yet. Run a diff first.</div>'; _status("0 saved.", "ok"); return; }
      mine.sort(function (a, b) { return String(b.id).localeCompare(String(a.id)); });
      _renderStepper(mine, '<div class="_cdl_savedhdr">' + mine.length + ' saved record(s) in IDB (negotiation_log)</div>');
      _status(mine.length + " saved record(s).", "ok");
    }).catch(function (e) { _status("Load failed: " + (e && e.message || "unknown"), "err"); });
  }

  function _renderStepper(items, summaryHtml) {
    _stepItems = items || []; _stepIdx = 0;
    if (!_stepItems.length) { resultsEl.innerHTML = '<div class="_cdl_empty">No clauses.</div>'; return; }
    resultsEl.innerHTML = (summaryHtml || "") +
      '<div class="_cdl_nav">' +
        '<button class="_cdl_btn _cdl_btn_ghost _cdl_btn_sm" id="_cdl_prev">◀ Prev</button>' +
        '<span class="_cdl_navpos" id="_cdl_navpos"></span>' +
        '<button class="_cdl_btn _cdl_btn_ghost _cdl_btn_sm" id="_cdl_next">Next ▶</button>' +
        '<select class="_cdl_select _cdl_jump" id="_cdl_jump"></select>' +
        '<label class="_cdl_chk"><input type="checkbox" id="_cdl_onlychg" checked> only changed</label>' +
      "</div>" +
      '<div id="_cdl_box"></div>';
    root.querySelector("#_cdl_prev").onclick = function () { _step(-1); };
    root.querySelector("#_cdl_next").onclick = function () { _step(1); };
    root.querySelector("#_cdl_jump").onchange = function () { _stepIdx = Number(this.value) || 0; _renderStep(); };
    root.querySelector("#_cdl_onlychg").onchange = function () { _stepIdx = 0; _renderStep(); };
    _renderStep();
  }

  function _visibleIdxList() {
    var only = root.querySelector("#_cdl_onlychg");
    var onlyChanged = only ? only.checked : false;
    var list = [];
    _stepItems.forEach(function (it, k) { if (!onlyChanged || it.state !== "unchanged") list.push(k); });
    if (!list.length) { for (var k = 0; k < _stepItems.length; k++) list.push(k); }
    return list;
  }

  function _renderStep() {
    var vis = _visibleIdxList();
    if (_stepIdx < 0) _stepIdx = 0;
    if (_stepIdx >= vis.length) _stepIdx = vis.length - 1;
    var item = _stepItems[vis[_stepIdx]];
    var box = root.querySelector("#_cdl_box");
    box.innerHTML = _cdlRenderCard(item);
    _wireCards(box);
    root.querySelector("#_cdl_navpos").innerHTML = (_stepIdx + 1) + " of " + vis.length + " · <b>" + item.state.toUpperCase() + "</b>";
    root.querySelector("#_cdl_prev").disabled = (_stepIdx <= 0);
    root.querySelector("#_cdl_next").disabled = (_stepIdx >= vis.length - 1);
    var opts = "";
    vis.forEach(function (realK, vi) {
      var it = _stepItems[realK];
      opts += '<option value="' + vi + '"' + (vi === _stepIdx ? " selected" : "") + ">" +
        (vi + 1) + ". [" + it.state + "] " + _cdlEsc((it.heading || "(untitled)").slice(0, 48)) + "</option>";
    });
    root.querySelector("#_cdl_jump").innerHTML = opts;
  }

  function _step(delta) {
    var vis = _visibleIdxList();
    _stepIdx = Math.max(0, Math.min(vis.length - 1, _stepIdx + delta));
    _renderStep();
  }

  function _wireCards(scope) {
    Array.prototype.forEach.call(scope.querySelectorAll("[data-cdl-toggle]"), function (b) {
      b.onclick = function () {
        var card = b.closest("._cdl_card");
        var which = b.getAttribute("data-cdl-toggle");
        Array.prototype.forEach.call(card.querySelectorAll("._cdl_pane"), function (p) {
          p.style.display = (p.getAttribute("data-cdl-pane") === which) ? "block" : "none";
        });
        Array.prototype.forEach.call(card.querySelectorAll("[data-cdl-toggle]"), function (x) {
          x.classList.toggle("_cdl_seg_active", x === b);
        });
      };
    });
  }
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.register) return;

  function _open() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedClauseDiffLab"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showClauseDiffLab !== "function") {
      eli.log.event("tool", "clause_diff_lab_fn_missing", {});
      if (typeof showToast === "function") showToast("Clause Diff Lab failed to load", "err");
      return;
    }
    try { window.showClauseDiffLab(eli); }
    catch (e) {
      eli.log.event("tool", "clause_diff_lab_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({ tile: { app_clause_diff_lab: _open } });
  eli.log.event("tool", "clause_diff_lab_initialized", {});
}

